import{_ as l,a0 as o,w as d,s as h,ao as t,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"回顾一下 Python 3.4 中的枚举 | LCTT x X-CMD","titleTemplate":false,"description":"回顾一下 Python 3.4 中的枚举 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"回顾一下 Python 3.4 中的枚举 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"回顾一下 Python 3.4 中的枚举 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210516 Looking back at what Python 3.4 did for enum","title":"回顾一下 Python 3.4 中的枚举","tag":"202105","desc":""},"relativePath":"202105/20210516 Looking back at what Python 3.4 did for enum.md","filePath":"[post].md"}'),r={name:"202105/20210516 Looking back at what Python 3.4 did for enum.md"};function c(u,s,g,k,b,f){const n=o("Link");return d(),h("div",null,[s[18]||(s[18]=t('<h1 id="回顾一下-python-3-4-中的枚举" tabindex="-1">回顾一下 Python 3.4 中的枚举 <a class="header-anchor" href="#回顾一下-python-3-4-中的枚举" aria-label="Permalink to “回顾一下 Python 3.4 中的枚举”">​</a></h1><blockquote><p>另外探索一些未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/30/230947j19r2772m12tccrh.jpg" alt=""></p><p>这是 Python 3.x 首发特性系列文章的第五篇。Python 3.4 在 2014 年首次发布，尽管它已经发布了很长时间，但它引入的许多特性都没有被充分利用，而且相当酷。下面是其中的三个。</p><h3 id="枚举" tabindex="-1">枚举 <a class="header-anchor" href="#枚举" aria-label="Permalink to “枚举”">​</a></h3>',5)),p("p",null,[s[1]||(s[1]=a("我最喜欢的逻辑谜题之一是自我描述的 ",-1)),e(n,{href:"https://en.wikipedia.org/wiki/The_Hardest_Logic_Puzzle_Ever"},{default:i(()=>[...s[0]||(s[0]=[a("史上最难的逻辑谜题",-1)])]),_:1}),s[2]||(s[2]=a("。在其中，它谈到了三个“神”，他们被称为 A、B 和 C，他们的身份是真、假和随机，按一定顺序排列。你可以问他们问题，但他们只用神的语言回答，其中 “da” 和 “ja” 表示 “是” 和 “不是”，但你不知道哪个是哪个。",-1))]),s[19]||(s[19]=t(`<p>如果你决定使用 Python 来解决这个问题，你将如何表示神的名字和身份以及神的语言中的词语？传统的答案是使用字符串。然而，字符串的拼写错误可能会带来灾难性的后果。</p><p>如果在解题的关键部分，你用字符串 “jaa” 而不是 “ja” 进行比较，你就会得到一个错误的答案。虽然谜题没有说明风险是什么，但这可能是最好的避免方式。</p><p><code>enum</code> 模块让你能够以一种可调试但安全的方式来定义这些东西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import enum</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@enum.unique</span></span>
<span class="line"><span>class Name(enum.Enum):</span></span>
<span class="line"><span>    A = enum.auto()</span></span>
<span class="line"><span>    B = enum.auto()</span></span>
<span class="line"><span>    C = enum.auto()</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>@enum.unique</span></span>
<span class="line"><span>class Identity(enum.Enum):</span></span>
<span class="line"><span>    RANDOM = enum.auto()</span></span>
<span class="line"><span>    TRUE = enum.auto()</span></span>
<span class="line"><span>    FALSE = enum.auto()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>       </span></span>
<span class="line"><span>@enum.unique</span></span>
<span class="line"><span>class Language(enum.Enum):</span></span>
<span class="line"><span>    ja = enum.auto()</span></span>
<span class="line"><span>    da = enum.auto()</span></span></code></pre></div><p>枚举的一个好处是，在调试日志或异常中，枚举的呈现方式是有帮助的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>name = Name.A</span></span>
<span class="line"><span>identity = Identity.RANDOM</span></span>
<span class="line"><span>answer = Language.da</span></span>
<span class="line"><span>print(&quot;I suspect&quot;, name, &quot;is&quot;, identity, &quot;because they answered&quot;, answer)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    I suspect Name.A is Identity.RANDOM because they answered Language.da</span></span></code></pre></div><h3 id="functools-singledispatch" tabindex="-1">functools.singledispatch <a class="header-anchor" href="#functools-singledispatch" aria-label="Permalink to “functools.singledispatch”">​</a></h3><p>在开发游戏的“基础设施”层时，你想通用地处理各种游戏对象，但仍然允许这些对象自定义动作。为了使这个例子更容易解释，假设这是一个基于文本的游戏。当你使用一个对象时，大多数情况下，它只会打印 <code>You are using &lt;x&gt;</code>。但是使用一把特殊的剑可能需要随机滚动，否则会失败。</p><p>当你获得一个物品时，它通常会被添加到库存中。然而，一块特别重的石头会砸碎一个随机物品。如果发生这种情况，库存中会失去该物体。</p><p>处理这个问题的一个方法是在物品上设置 <code>use</code> 和 <code>acquire</code> 方法。随着游戏复杂性的增加，这些方法会越来越多，使游戏对象变得难以编写。</p><p>相反，<code>functools.singledispatch</code> 允许你以安全和尊重命名空间的方式追溯性地添加方法。</p><p>你可以定义没有行为的类：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class Torch:</span></span>
<span class="line"><span>    name=&quot;torch&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class Sword:</span></span>
<span class="line"><span>    name=&quot;sword&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class Rock:</span></span>
<span class="line"><span>    name=&quot;rock&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import functools</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@functools.singledispatch</span></span>
<span class="line"><span>def use(x):</span></span>
<span class="line"><span>    print(&quot;You use&quot;, x.name)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@functools.singledispatch</span></span>
<span class="line"><span>def acquire(x, inventory):</span></span>
<span class="line"><span>    inventory.add(x)</span></span></code></pre></div><p>对于火炬来说，这些通用的实现已经足够了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inventory = set()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def deploy(thing):</span></span>
<span class="line"><span>    acquire(thing, inventory)</span></span>
<span class="line"><span>    use(thing)</span></span>
<span class="line"><span>    print(&quot;You have&quot;, [item.name for item in inventory])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deploy(Torch())</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    You use torch</span></span>
<span class="line"><span>    You have [&#39;torch&#39;]</span></span></code></pre></div><p>然而，剑和石头需要一些专门的功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import random</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@use.register(Sword)</span></span>
<span class="line"><span>def use_sword(sword):</span></span>
<span class="line"><span>    print(&quot;You try to use&quot;, sword.name)</span></span>
<span class="line"><span>    if random.random() &lt; 0.9:</span></span>
<span class="line"><span>        print(&quot;You succeed&quot;)</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;You fail&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deploy(sword)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    You try to use sword</span></span>
<span class="line"><span>    You succeed</span></span>
<span class="line"><span>    You have [&#39;sword&#39;, &#39;torch&#39;]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import random</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@acquire.register(Rock)</span></span>
<span class="line"><span>def acquire_rock(rock, inventory):</span></span>
<span class="line"><span>    to_remove = random.choice(list(inventory))</span></span>
<span class="line"><span>    inventory.remove(to_remove)</span></span>
<span class="line"><span>    inventory.add(rock)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deploy(Rock())</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    You use rock</span></span>
<span class="line"><span>    You have [&#39;sword&#39;, &#39;rock&#39;]</span></span></code></pre></div><p>岩石可能压碎了火炬，但你的代码更容易阅读。</p><h3 id="pathlib" tabindex="-1">pathlib <a class="header-anchor" href="#pathlib" aria-label="Permalink to “pathlib”">​</a></h3><p>从一开始，Python 中文件路径的接口就是“智能字符串操作”。现在，通过 <code>pathlib</code>，Python 有了一种面向对象的方法来操作路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import pathlib</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gitconfig = pathlib.Path.home() / &quot;.gitconfig&quot;</span></span>
<span class="line"><span>text = gitconfig.read_text().splitlines()</span></span></code></pre></div><p>诚然，用 <code>/</code> 作为操作符来生成路径名有点俗气，但在实践中却不错。像 <code>.read_text()</code> 这样的方法允许你从小文件中获取文本，而不需要手动打开和关闭文件句柄。</p><p>这使你可以集中精力处理重要的事情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for line in text:</span></span>
<span class="line"><span>    if not line.strip().startswith(&quot;name&quot;):</span></span>
<span class="line"><span>        continue</span></span>
<span class="line"><span>    print(line.split(&quot;=&quot;)[1])</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>     Moshe Zadka</span></span></code></pre></div><h3 id="欢迎来到-2014-年" tabindex="-1">欢迎来到 2014 年 <a class="header-anchor" href="#欢迎来到-2014-年" aria-label="Permalink to “欢迎来到 2014 年”">​</a></h3><p>Python 3.4 大约在七年前就发布了，但是在这个版本中首次出现的一些功能非常酷，而且没有得到充分利用。如果你还没使用，那么将他们添加到你的工具箱中。</p><hr>`,35)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/5/python-34-features"},{default:i(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/21/5/python-34-features",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:i(()=>[...s[5]||(s[5]=[a("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const C=l(r,[["render",c]]);export{v as __pageData,C as default};
